export type ParsedSettleChainProofInstruction<
  TProgram extends string = typeof BUCKSPAY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    /** Pays the rent of the records and of the draws account; the fee payer in the usual case. */
    payer: TAccountMetas[0]
    config: TAccountMetas[1]
    /** reported as `MintNotEnabled`. */
    zkMint: TAccountMetas[2]
    lock: TAccountMetas[3]
    ledger: TAccountMetas[4]
    escrow: TAccountMetas[5]
    mint: TAccountMetas[6]
    /**
     * Any token account of the mint; the handler requires its owner to be the account the note
     * pays, which the proofs bind.
     */
    destination: TAccountMetas[7]
    feeAccount: TAccountMetas[8]
    draws: TAccountMetas[9]
    /** The messages, when they did not fit the transaction; closed to its payer, who is the signer. */
    buffer?: TAccountMetas[10] | undefined
    tokenProgram: TAccountMetas[11]
    systemProgram: TAccountMetas[12]
  }
  data: SettleChainProofInstructionData
}

export function parseSettleChainProofInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleChainProofInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 13,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === BUCKSPAY_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      config: getNextAccount(),
      zkMint: getNextAccount(),
      lock: getNextAccount(),
      ledger: getNextAccount(),
      escrow: getNextAccount(),
      mint: getNextAccount(),
      destination: getNextAccount(),
      feeAccount: getNextAccount(),
      draws: getNextAccount(),
      buffer: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSettleChainProofInstructionDataDecoder().decode(instruction.data),
  }
}
